const sales = [
    { sku: "A1", qty: 3, price: 200 },
    { sku: "B7", qty: 1, price: 950 },
    { sku: "A1", qty: 2, price: 200 },
    { sku: "C3", qty: 10, price: 40 }
];
const revenue = sales.reduce((acc, { sku, qty, price }) => {
    acc[sku] = (acc[sku] ?? 0) + qty * price;
    return acc;
}, {});
const top = Object.entries(revenue)
    .sort(([, a], [, b]) => b - a)
    .map(([sku, amt]) => sku + ":" + amt);
console.log(top.join(" "));

